<script setup lang="ts">
import type { ApiProblem } from '~/types/api'; import { formatDate } from '~/utils/formatters'
definePageMeta({ middleware: 'auth' }); const route = useRoute(); const id = Number(route.params.id); const { find, update, resetPassword } = useUsers(); const { data: account } = await useAsyncData(`user-${id}`, () => find(id)); if (!account.value) throw createError({ statusCode: 404 }); const form = reactive({ name: account.value.name, email: account.value.email, status: account.value.status }); const password = reactive({ value: '', confirmation: '' }); const errors = ref<Record<string, string[]>>({}); const saving = ref(false)
async function saveAccount() { saving.value = true; errors.value = {}; try { account.value = await update(id, { ...form, role_id: account.value!.role.id }) } catch (error) { const problem = error as ApiProblem; errors.value = problem.errors ?? { form: [problem.message] } } finally { saving.value = false } }
async function reset() { saving.value = true; errors.value = {}; try { await resetPassword(id, password.value, password.confirmation); password.value = ''; password.confirmation = '' } catch (error) { const problem = error as ApiProblem; errors.value = problem.errors ?? { form: [problem.message] } } finally { saving.value = false } }
</script>
<template><div v-if="account" class="page-shell"><PageHeader :title="account.name" :description="account.email"><template #actions><StatusBadge :status="account.status" /></template></PageHeader><div class="grid gap-6 lg:grid-cols-2"><BaseCard><h2 class="mb-4 font-semibold text-[#102a43]">Account details</h2><div class="space-y-4"><FormField for="user-name" label="Name" :error="errors.name?.[0]"><BaseInput id="user-name" v-model="form.name" /></FormField><FormField for="user-email" label="Email" :error="errors.email?.[0]"><BaseInput id="user-email" v-model="form.email" type="email" /></FormField><FormField for="user-status" label="Status" :error="errors.status?.[0]"><BaseSelect id="user-status" v-model="form.status" :options="['active', 'inactive', 'suspended'].map(value => ({ label: value, value }))" /></FormField><p class="border-t border-[#e5ecf3] pt-4 text-sm text-[#60728a]">Last login: {{ account.last_login_at ? formatDate(account.last_login_at) : 'Never' }}</p><BaseButton :loading="saving" @click="saveAccount">Save account</BaseButton></div></BaseCard><BaseCard><h2 class="mb-4 font-semibold text-[#102a43]">Reset password</h2><div class="space-y-4"><FormField for="reset-password" label="Temporary password" :error="errors.password?.[0]"><BaseInput id="reset-password" v-model="password.value" type="password" /></FormField><FormField for="reset-confirmation" label="Confirm password"><BaseInput id="reset-confirmation" v-model="password.confirmation" type="password" /></FormField><p class="text-xs text-[#60728a]">The user will be required to replace this password after signing in.</p><BaseButton :loading="saving" @click="reset">Reset password</BaseButton></div></BaseCard></div><p v-if="errors.form" class="text-sm text-red-600">{{ errors.form[0] }}</p></div></template>
